<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Modal } from 'ant-design-vue'
import message from 'ant-design-vue/es/message'
import { FilePlus2, RefreshCw, Search, SlidersHorizontal, FileSearch, Trash2 } from '@lucide/vue'
import { researchTaskApi } from '@/api/researchTask'
import AppShell from '@/components/AppShell.vue'
import PageHeader from '@/components/PageHeader.vue'
import StatusTag from '@/components/StatusTag.vue'
import { formatDate, isActiveTask, taskStatusMeta, taskStatusValues } from '@/utils/display'
import type { ResearchTask, TaskStatus } from '@/types'
const route = useRoute(); const router = useRouter(); const workspaceId = computed(() => String(route.params.workspaceId)); const tasks = ref<ResearchTask[]>([]); const loading = ref(false); const deletingTaskId = ref<string | null>(null); const query = ref(''); const status = ref<TaskStatus | 'ALL'>('ALL')
const filteredTasks = computed(() => tasks.value.filter((task) => (status.value === 'ALL' || task.status === status.value) && (!query.value.trim() || task.query.toLowerCase().includes(query.value.trim().toLowerCase())))); const runningCount = computed(() => tasks.value.filter((task) => isActiveTask(task.status)).length); const completedCount = computed(() => tasks.value.filter((task) => task.status === 'COMPLETED').length); const failedCount = computed(() => tasks.value.filter((task) => task.status === 'FAILED').length); const statusOptions = taskStatusValues
async function load() { loading.value = true; try { tasks.value = await researchTaskApi.list(workspaceId.value) } catch (error) { message.error(error instanceof Error ? error.message : '任务加载失败') } finally { loading.value = false } }; function openTask(task: ResearchTask) { router.push({ name: 'task-detail', params: { workspaceId: workspaceId.value, taskId: task.taskId } }) }; function isDeletable(task: ResearchTask) { return ['COMPLETED', 'FAILED', 'CANCELLED'].includes(task.status) }; function confirmDelete(task: ResearchTask) { Modal.confirm({ title: '删除研究任务？', content: '将永久删除该任务的报告、引用、执行事件和计划记录，且无法恢复。审计与成本账本会保留。', okText: '删除', okType: 'danger', cancelText: '取消', onOk: async () => { deletingTaskId.value = task.taskId; try { await researchTaskApi.delete(workspaceId.value, task.taskId); tasks.value = tasks.value.filter((item) => item.taskId !== task.taskId); message.success('研究任务已删除') } catch (error) { message.error(error instanceof Error ? error.message : '任务删除失败'); throw error } finally { deletingTaskId.value = null } } }) }; onMounted(load)
</script>
<template><AppShell><div class="page-content"><PageHeader eyebrow="RESEARCH TASKS" title="研究任务" description="从问题到报告，查看每一次研究执行的进展。"><a-button type="primary" @click="router.push({ name: 'task-new', params: { workspaceId } })"><FilePlus2 :size="16" /> 新建研究任务</a-button></PageHeader><section class="section-band"><div class="metric-row"><div class="metric"><div class="metric-label">全部任务</div><div class="metric-value">{{ tasks.length }}</div><div class="metric-note">当前工作空间</div></div><div class="metric"><div class="metric-label">进行中</div><div class="metric-value">{{ runningCount }}</div><div class="metric-note">实时执行</div></div><div class="metric"><div class="metric-label">已完成</div><div class="metric-value">{{ completedCount }}</div><div class="metric-note">可查看报告</div></div><div class="metric"><div class="metric-label">需关注</div><div class="metric-value">{{ failedCount }}</div><div class="metric-note">执行失败</div></div></div></section><div class="toolbar"><div class="toolbar-left"><a-input v-model:value="query" allow-clear placeholder="搜索研究问题" style="width: 250px"><template #prefix><Search :size="15" /></template></a-input><a-select v-model:value="status" style="width: 150px" :options="[{ label: '全部状态', value: 'ALL' }, ...statusOptions.map((item) => ({ label: taskStatusMeta[item].label, value: item }))]" /><span class="filter-hint"><SlidersHorizontal :size="14" /> {{ filteredTasks.length }} 条结果</span></div><div class="toolbar-right"><a-button :loading="loading" @click="load"><RefreshCw :size="15" /> 刷新</a-button></div></div><a-table :data-source="filteredTasks" :loading="loading" :pagination="{ pageSize: 8, hideOnSinglePage: true }" row-key="taskId" @row-click="openTask"><a-table-column key="query" title="研究问题" :width="380"><template #default="{ record }"><button class="table-link" @click.stop="openTask(record)">{{ record.query }}</button><div class="table-subline">{{ record.taskId }}</div></template></a-table-column><a-table-column key="status" title="状态" :width="130"><template #default="{ record }"><StatusTag :status="record.status" /></template></a-table-column><a-table-column key="progress" title="进度" :width="190"><template #default="{ record }"><div class="progress-cell"><a-progress :percent="record.progress" size="small" :show-info="false" /><span>{{ record.progress }}%</span></div></template></a-table-column><a-table-column key="createdAt" title="创建时间" :width="160"><template #default="{ record }"><span class="muted">{{ formatDate(record.createdAt) }}</span></template></a-table-column><a-table-column key="action" title="" :width="180"><template #default="{ record }"><a-button type="link" size="small" @click.stop="openTask(record)">查看详情</a-button><a-tooltip :title="isDeletable(record) ? '永久删除任务及其研究数据' : '进行中的任务不能删除，请先取消并等待任务结束'"><a-button type="link" danger size="small" :loading="deletingTaskId === record.taskId" :disabled="!isDeletable(record)" @click.stop="confirmDelete(record)"><Trash2 :size="14" /> 删除</a-button></a-tooltip></template></a-table-column><template #emptyText><div class="empty-state"><FileSearch :size="28" /><h3>{{ query || status !== 'ALL' ? '没有匹配的任务' : '还没有研究任务' }}</h3><p>{{ query || status !== 'ALL' ? '尝试调整筛选条件' : '创建一个问题，开始你的第一次研究。' }}</p></div></template></a-table></div></AppShell></template>
